function Reveal({ children, delay = 0, skew = true }: {
  children: ReactNode; delay?: number; skew?: boolean;
}) {
  return (
    <span style={{ display: "block", overflow: "hidden" }}>
      <motion.span style={{ display: "block" }}
        initial={{ y: "115%", skewY: skew ? 3 : 0 }}
        whileInView={{ y: 0, skewY: 0 }}
        viewport={{ once: true }}
        transition={{ duration: 0.85, delay, ease: [0.16, 1, 0.3, 1] }}>
        {children}
      </motion.span>
    </span>
  );
}

function PImg({ src, alt, style }: { src: string; alt: string; style?: CSSProperties }) {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start end", "end start"] });
  const y = useTransform(scrollYProgress, [0, 1], ["-15%", "15%"]);
  const scale = useTransform(scrollYProgress, [0, 0.5, 1], [1.2, 1.06, 1.2]);
  return (
    <div ref={ref} style={{ overflow: "hidden", ...style }}>
      <motion.img src={src} alt={alt} style={{ width: "100%", height: "100%", objectFit: "cover", y, scale }} />
    </div>
  );
}

function AnimNum({ n, suffix = "" }: { n: number; suffix?: string }) {
  const ref = useRef<HTMLSpanElement>(null);
  const inViewRef = useRef(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting && !inViewRef.current) {
        inViewRef.current = true;
        let start = 0;
        const step = () => {
          start += Math.ceil(n / 60);
          if (start >= n) { el.textContent = n + suffix; return; }
          el.textContent = start + suffix;
          requestAnimationFrame(step);
        };
        requestAnimationFrame(step);
      }
    }, { threshold: 0.5 });
    obs.observe(el);
    return () => obs.disconnect();
  }, [n, suffix]);
  return <span ref={ref}>0{suffix}</span>;
}

function PScrollBg({ sectionRef }: { sectionRef: RefObject<HTMLDivElement | null> }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imgCacheRef = useRef<(HTMLImageElement | null)[]>([]);
  const loadedRef = useRef<boolean[]>([]);
  const currentFrameRef = useRef(0);
  const targetFrameRef = useRef(0);
  const rafRef = useRef<number | null>(null);

  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ["start end", "end start"],
  });

  useEffect(() => {
    imgCacheRef.current = new Array(VIDEO_FRAMES.length).fill(null);
    loadedRef.current = new Array(VIDEO_FRAMES.length).fill(false);

    VIDEO_FRAMES.forEach((src, i) => {
      const img = new Image();
      img.onload = () => {
        imgCacheRef.current[i] = img;
        loadedRef.current[i] = true;
        if (i === 0) drawFrame(0);
      };
      img.src = src;
    });
  }, []);

  const drawFrame = useCallback((index: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const img = imgCacheRef.current[index];
    if (!img) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const cw = canvas.width;
    const ch = canvas.height;
    const iw = img.naturalWidth;
    const ih = img.naturalHeight;

    const scale = Math.max(cw / iw, ch / ih);
    const sw = iw * scale;
    const sh = ih * scale;
    const sx = (cw - sw) / 2;
    const sy = (ch - sh) / 2;

    ctx.clearRect(0, 0, cw, ch);
    ctx.drawImage(img, sx, sy, sw, sh);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ro = new ResizeObserver(() => {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
      drawFrame(currentFrameRef.current);
    });
    ro.observe(canvas);
    return () => ro.disconnect();
  }, [drawFrame]);

  useEffect(() => {
    const tick = () => {
      const diff = targetFrameRef.current - currentFrameRef.current;
      if (Math.abs(diff) > 0.5) {
        currentFrameRef.current += diff * 0.55;
        const idx = Math.round(currentFrameRef.current);
        const clamped = Math.max(0, Math.min(VIDEO_FRAMES.length - 1, idx));
        drawFrame(clamped);
      }
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => { if (rafRef.current) cancelAnimationFrame(rafRef.current); };
  }, [drawFrame]);

  useMotionValueEvent(scrollYProgress, "change", (progress: number) => {
    const clamped = Math.max(0, Math.min(1, progress));
    targetFrameRef.current = clamped * (VIDEO_FRAMES.length - 1);
  });

  return (
    <canvas
      ref={canvasRef}
      style={{
        position: "absolute",
        inset: 0,
        width: "100%",
        height: "100%",
        display: "block",
      }}
    />
  );
}

